  const tas = [];
  let ordre = 0;

  function estAvant(a, b) {
    if (a.priorite !== b.priorite) {
      return a.priorite < b.priorite;
    }
    return a.ordre < b.ordre;
  }

  function monter(index) {
    while (index > 0) {
      const parent = Math.floor((index - 1) / 2);
      if (estAvant(tas[index], tas[parent])) {
        [tas[index], tas[parent]] = [tas[parent], tas[index]];
        index = parent;
      } else {
        break;
      }
    }
  }

  function descendre(index) {
    const longueur = tas.length;

    while (true) {
      const gauche = 2 * index + 1;
      const droite = 2 * index + 2;
      let plusPetit = index;

      if (gauche < longueur && estAvant(tas[gauche], tas[plusPetit])) {
        plusPetit = gauche;
      }

      if (droite < longueur && estAvant(tas[droite], tas[plusPetit])) {
        plusPetit = droite;
      }

      if (plusPetit === index) {
        break;
      }

      [tas[index], tas[plusPetit]] = [tas[plusPetit], tas[index]];
      index = plusPetit;
    }
  }

  return {
    enqueue(valeur, priorite) {
      let p = 0;

      if (priorite !== undefined) {
        try {
          p = Number(priorite);
        } catch (e) {
          p = 0;
